DECLARE @no varchar(31)=?,@name nvarchar(642)=?,@kana nvarchar(74)=?,@year smallint=?,@grade varchar(2)=?,@class bigint=?,@unassigned bit=?,@prefecture varchar(2)=?,@phone varchar(16)=?,@from date=?,@to date=?,@s1 varchar(2)=?,@s2 varchar(2)=?,@s3 varchar(2)=?,@s4 varchar(2)=?; DECLARE @offset int=?,@size int=?; SELECT CONVERT(varchar(19),s.student_id),s.student_no,s.student_name,s.student_name_kana,CONVERT(char(10),s.birth_date,23),c.school_year,COALESCE(g.code_name,N'不整合'),c.class_code,c.class_name,COALESCE(e.code_name,N'不整合'),COALESCE(p.code_name,N'不整合')+s.address_line1,s.phone_number,CONVERT(varchar(19),SWITCHOFFSET(s.updated_at,'+09:00'),120) FROM dbo.m_student s LEFT JOIN dbo.m_class c ON c.class_id=s.class_id LEFT JOIN dbo.m_code g ON g.category_id=c.grade_category AND g.code_value=c.grade_code LEFT JOIN dbo.m_code e ON e.category_id=s.enrollment_category AND e.code_value=s.enrollment_status_code LEFT JOIN dbo.m_code p ON p.category_id=s.prefecture_category AND p.code_value=s.prefecture_code WHERE s.is_deleted=0 AND (@no IS NULL OR s.student_no LIKE @no ESCAPE '!') AND (@name IS NULL OR s.name_key LIKE @name ESCAPE '!') AND (@kana IS NULL OR s.kana_key LIKE @kana ESCAPE '!') AND (@year IS NULL OR c.school_year=@year) AND (@grade IS NULL OR c.grade_code=@grade) AND (@class IS NULL OR s.class_id=@class) AND (@unassigned=0 OR s.class_id IS NULL) AND (@prefecture IS NULL OR s.prefecture_code=@prefecture) AND (@phone IS NULL OR s.phone_number=@phone OR s.emergency_phone_number=@phone) AND (@from IS NULL OR s.admission_date>=@from) AND (@to IS NULL OR s.admission_date<=@to) AND ((@s1 IS NULL AND @s2 IS NULL AND @s3 IS NULL AND @s4 IS NULL) OR s.enrollment_status_code IN (@s1,@s2,@s3,@s4)) ORDER BY s.updated_at ASC,s.student_id ASC OFFSET @offset ROWS FETCH NEXT @size ROWS ONLY;
